"""Real JEE Main questions — Chemistry Unit 10: p-Block Elements (groups 13–18). Our own solutions; chk evaluates
each statement against a facts table (NCERT values) or re-derives counts with vsepr.py. Skipped: a group-14 match
whose options were cut off in the paper scan, and analysis/organic items that only mention a p-block reagent."""
from common import new_registry, pick, near, verify
from vsepr import vsepr as V
from ptdata import RAD, EN, IE1
P, add = new_registry()
def st(a, b, opts):
    want = {(True, True): ('both', 'true'), (False, False): ('both', 'false'), (True, False): ('i', 'ii false'), (False, True): ('i false', 'ii true')}[(a, b)]
    for i, o in enumerate(opts):
        lo = o.lower().replace('statements', 'statement').replace('correct', 'true').replace('incorrect', 'false').replace('intrue', 'false')
        lo = lo.replace('are ', '').replace('is ', '').replace('  ', ' ')
        if want[0] == 'both' and lo.startswith('both') and lo.endswith(want[1]): return i + 1
        if want == ('i', 'ii false') and lo.startswith('statement i true') and 'ii false' in lo: return i + 1
        if want == ('i false', 'ii true') and lo.startswith('statement i false') and 'ii true' in lo: return i + 1
    raise AssertionError(opts)
SA = ['Both Statement I and Statement II are false', 'Both Statement I and Statement II are true', 'Statement I is true but Statement II is false', 'Statement I is false but Statement II is true']
SB = ['Statement I is true but Statement II is false', 'Statement I is false but Statement II is true', 'Both Statement I and Statement II are false', 'Both Statement I and Statement II are true']
SC = ['Both Statement I and Statement II are False', 'Statement I is false but Statement II are true', 'Statement I is true but Statement II is false', 'Both Statement I and Statement II are true']
SD = ['Statement I is incorrect but Statement II is correct', 'Both Statement I and Statement II are correct', 'Both Statement I and Statement II are incorrect', 'Statement I is correct but Statement II is incorrect']
SE = ['Statement I is correct but Statement II is incorrect', 'Both Statement I and Statement II are correct', 'Both Statement I and Statement II are incorrect', 'Statement I is incorrect but Statement II is correct']
SF = ['Both Statement I and Statement II are true', 'Both Statement I and Statement II are false', 'Statement I is true but Statement II is false', 'Statement I is false but Statement II is true']
SG = ['Statement I is true but statement II is false', 'Statement I is false but statement II is true', 'Both statement I and statement II are false', 'Both statement I and statement II are true']
SH = ['Both Statement I and Statement II are true', 'Statement I is false but Statement II is true', 'Both Statement I and Statement II are false', 'Statement I is true but Statement II is false']
SI = ['Statement I is false but Statement II is true', 'Both Statement I and Statement II are true', 'Statement I is true but Statement II is false', 'Both Statement I and Statement II are false']
AR = ['Both (A) and (R) are correct but (R) Is not the correct explanation of (A)', 'Both (A) and (R) are correct and (R) is the correct explanation of (A)', '(A) is true but (R) is false', '(A) is false but (R) is true']
